<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
const props=defineProps<{companyId:string;ready:boolean}>(),emit=defineEmits<{busy:[value:boolean]}>()
const data=ref<any>(null),busy=ref(false),error=ref(''),notice=ref('')
const form=reactive({name:'',subject:'',body:'',segment:'all',scheduledAt:''})
const automations=ref<any[]>([])
const api=(path:string,options:any={})=>$fetch<any>('/api/crm/campaigns'+path,{...options,headers:{'x-company-id':props.companyId},retry:0})
async function load(){data.value=await api('');automations.value=['abandoned_cart','post_purchase'].map(kind=>data.value.automations.find((item:any)=>item.kind===kind)||{kind,enabled:false,delayHours:24,subject:'Thank you for visiting us',body:'Hi {name}, thank you for visiting us.'})}
async function run(work:()=>Promise<void>){if(busy.value)return;busy.value=true;emit('busy',true);error.value='';notice.value='';try{await work()}catch(e:any){error.value=e?.data?.statusMessage||e.message||'Campaign request failed.'}finally{busy.value=false;emit('busy',false)}}
async function create(){await api('',{method:'POST',body:{...form,scheduledAt:form.scheduledAt?new Date(form.scheduledAt).toISOString():undefined}});Object.assign(form,{name:'',subject:'',body:'',segment:'all',scheduledAt:''});await load();notice.value='Campaign draft saved. Review it before queueing.'}
async function action(id:string,value:string){await api('/'+id+'/'+value,{method:'POST'});await load();notice.value=value==='queue'?'Campaign queued for confirmed subscribers.':'Campaign cancelled.'}
async function saveAutomation(item:any){await api('/automations',{method:'PUT',body:item});await load();notice.value='Marketing automation saved.'}
onMounted(()=>{if(props.ready)void run(load)})
</script>
<template><section v-if="!ready" class="crm-panel"><h2 class="font-semibold">Email campaign setup is pending</h2><p class="mt-2 text-sm text-gray-500">Complete the existing email marketing installation and sender configuration to use campaigns here.</p></section><div v-else class="space-y-5"><p class="text-sm text-gray-500">Campaigns use confirmed email subscribers. CRM segments help sales follow-up; email audiences below retain their subscription rules. WhatsApp uses Connect’s separate client permissions.</p><p v-if="error" role="alert" class="crm-error">{{error}}</p><p v-if="notice" role="status" class="crm-success">{{notice}}</p>
  <div v-if="data" class="flex flex-wrap gap-2"><span v-for="(count,segment) in data.segmentCounts" :key="segment" class="crm-badge">{{segment}}: {{count}} eligible</span></div>
  <form class="crm-panel space-y-4" @submit.prevent="run(create)"><h2 class="font-semibold">New email campaign draft</h2><fieldset :disabled="busy" class="grid gap-4 sm:grid-cols-2"><label class="crm-label">Campaign name<input v-model="form.name" class="crm-input" maxlength="100" required/></label><label class="crm-label">Email subject<input v-model="form.subject" class="crm-input" maxlength="180" required/></label><label class="crm-label sm:col-span-2">Message<textarea v-model="form.body" class="crm-input" rows="5" maxlength="10000" placeholder="Use {name} for the subscriber’s name" required/></label><label class="crm-label">Confirmed subscriber audience<select v-model="form.segment" class="crm-input"><option v-for="segment in ['all','new','repeat','inactive','cart']" :key="segment" :value="segment">{{segment}}</option></select></label><label class="crm-label">Schedule (optional)<input v-model="form.scheduledAt" class="crm-input" type="datetime-local"/></label><div><UButton type="submit" :loading="busy">Save campaign draft</UButton></div></fieldset></form>
  <section class="crm-panel overflow-x-auto"><h2 class="mb-4 font-semibold">Campaigns</h2><table class="crm-table"><thead><tr><th>Campaign</th><th>Status</th><th>Delivery</th><th>Actions</th></tr></thead><tbody><tr v-for="row in data?.campaigns||[]" :key="row.id"><td>{{row.name}}<p class="crm-help">{{row.subject}} · {{row.segment}}</p></td><td>{{row.status}}</td><td>{{row.sentCount}} sent · {{row.pendingCount}} pending · {{row.failedCount}} failed</td><td><div class="flex gap-2"><button v-if="row.status==='DRAFT'" class="crm-button" :disabled="busy" @click="run(()=>action(row.id,'queue'))">Queue campaign</button><button v-if="['DRAFT','QUEUED'].includes(row.status)" class="crm-button" :disabled="busy" @click="run(()=>action(row.id,'cancel'))">Cancel campaign</button></div></td></tr></tbody></table><p v-if="!data?.campaigns?.length" class="crm-help p-4">No campaign drafts yet.</p></section>
  <section class="crm-panel space-y-4"><h2 class="font-semibold">Email automations</h2><form v-for="item in automations" :key="item.kind" class="space-y-3 rounded-lg border p-4 dark:border-gray-700" @submit.prevent="run(()=>saveAutomation(item))"><h3 class="text-sm font-medium">{{item.kind==='abandoned_cart'?'Abandoned cart':'Post-purchase follow-up'}}</h3><fieldset :disabled="busy" class="grid gap-3 sm:grid-cols-2"><label class="flex items-center gap-2 text-sm"><input v-model="item.enabled" type="checkbox"/> Enabled</label><label class="crm-label">Delay in hours<input v-model.number="item.delayHours" class="crm-input" type="number" min="1" max="720" required/></label><label class="crm-label sm:col-span-2">Subject<input v-model="item.subject" class="crm-input" maxlength="180" required/></label><label class="crm-label sm:col-span-2">Message<textarea v-model="item.body" class="crm-input" rows="3" maxlength="10000" required/></label><div><UButton type="submit" color="gray">Save automation</UButton></div></fieldset></form></section>
  <section v-if="data?.failedJobs?.length" class="crm-panel"><h2 class="mb-3 font-semibold">Delivery issues</h2><p v-for="row in data.failedJobs" :key="row.id" class="py-2 text-sm">{{row.email}} · {{row.attempts}} attempts · {{row.lastError}}</p></section>
</div></template>
